    /**
     * Calculate a simple direct transfer trajectory
     * This is a simplified model - assumes instant acceleration and straight-line travel
     * For more realism, we'd implement Hohmann transfers
     */
    public static Trajectory calculateDirectTransfer(Vector3D start, Vector3D end,
                                                     Spacecraft spacecraft) {
        double distance = start.distanceTo(end);

        // Simple model: accelerate to midpoint, decelerate to arrival
        // Assumes constant thrust at midpoint
        // Total deltaV = 2 * sqrt(2 * a * d/2) where a*t²/2 = d/2
        // Simplified: deltaV proportional to sqrt(distance)

        // More realistic approach: assume we want to arrive in reasonable time
        // Using vis-viva equation approximation for orbital transfers
        double deltaV = estimateDeltaVForDistance(distance);


        // Travel time based on distance and available deltaV
        // Simplified: time = distance / (average velocity)
        // Average velocity ~ deltaV / 2 (accelerate then decelerate)
        double averageVelocity = deltaV / 2.0;
        double travelTime = distance / averageVelocity;

        // Calculate fuel required using Tsiolkovsky equation
        double fuelRequired = spacecraft.getFuelRequiredForDeltaV(deltaV);

        return new Trajectory(start, end, deltaV, travelTime, fuelRequired, averageVelocity);
    }

    /**
     * Calculate Hohmann transfer between circular orbits
     * More realistic for orbital mechanics
     * NOTE: Only accurate for COPLANAR, CIRCULAR orbits
     * For inclined or elliptical orbits, use calculateGeneralTransfer()
     */
    public static Trajectory calculateHohmannTransfer(double r1, double r2,
                                                      double centralMass,
                                                      Spacecraft spacecraft) {
        // Semi-major axis of transfer ellipse
        double a = (r1 + r2) / 2.0;

        // Orbital velocities
        double v1 = Math.sqrt(PhysicsConstants.G * centralMass / r1);
        double v2 = Math.sqrt(PhysicsConstants.G * centralMass / r2);

        // Velocities at periapsis and apoapsis of transfer orbit
        double vp = Math.sqrt(PhysicsConstants.G * centralMass * (2.0/r1 - 1.0/a));
        double va = Math.sqrt(PhysicsConstants.G * centralMass * (2.0/r2 - 1.0/a));

        // Delta-v requirements
        double deltaV1 = Math.abs(vp - v1);  // Injection burn
        double deltaV2 = Math.abs(v2 - va);  // Circularization burn
        double totalDeltaV = deltaV1 + deltaV2;

        // Transfer time (half orbital period of transfer ellipse)
        double transferTime = Math.PI * Math.sqrt(Math.pow(a, 3) /
                (PhysicsConstants.G * centralMass));

        // Fuel required
        double fuelRequired = spacecraft.getFuelRequiredForDeltaV(totalDeltaV);

        Vector3D start = new Vector3D(r1, 0, 0);
        Vector3D end = new Vector3D(r2, 0, 0);

        return new Trajectory(start, end, totalDeltaV, transferTime, fuelRequired, v2);
    }

    public static boolean canUseHohmannTransfer(OrbitInitializer startOrbit,
                                                OrbitInitializer endOrbit) {
        double e1 = startOrbit.eccentricity();
        double e2 = endOrbit.eccentricity();
        double i1 = startOrbit.inclination();
        double i2 = endOrbit.inclination();

        boolean circularStart = e1 < 0.1;
        boolean circularEnd = e2 < 0.1;
        boolean coplanar = Math.abs(i2 - i1) < Math.toRadians(5.0);

        return circularStart && circularEnd && coplanar;
    }

    public static Trajectory calculateGeneralTransfer(OrbitInitializer startElements,
                                                      OrbitInitializer endElements,
                                                      double centralMass,
                                                      Spacecraft spacecraft) {

        double mu = PhysicsConstants.G * centralMass;

        // Extract starting orbit elements
        double a1 = startElements.semiMajorAxis();
        double e1 = startElements.eccentricity();
        double i1 = startElements.inclination();

        // Extract target orbit elements
        double a2 = endElements.semiMajorAxis();
        double e2 = endElements.eccentricity();
        double i2 = endElements.inclination();

        // Calculate inclination change
        double deltaI = Math.abs(i2 - i1);

        // For small inclination changes, we can combine with Hohmann-like transfer
        // For large changes, we need dedicated plane change maneuvers

        // Calculate base Hohmann transfer delta-v
        double aTransfer = (a1 + a2) / 2.0;

        // Velocities (approximating circular for elliptical)
        double v1 = Math.sqrt(mu / a1);
        double v2 = Math.sqrt(mu / a2);
        double vp = Math.sqrt(mu * (2.0/ a1 - 1.0/aTransfer));
        double va = Math.sqrt(mu * (2.0/ a2 - 1.0/aTransfer));

        double deltaV1 = Math.abs(vp - v1);
        double deltaV2 = Math.abs(v2 - va);

        // Add plane change delta-v
        // Most efficient to do plane change at the highest point (lowest velocity)
        // Delta-v for plane change: 2 * v * sin(Δi/2)
        double planeChangeDeltaV = 0.0;

        if (deltaI > 0.001) { // More than ~0.06 degrees
            // Do plane change at apoapsis of transfer orbit (lowest velocity)
            planeChangeDeltaV = 2.0 * va * Math.sin(deltaI / 2.0);
        }

        // Account for eccentricity differences
        // More elliptical orbits require additional delta-v
        double eccentricityPenalty = Math.abs(e2 - e1) * v2 * 0.5; // Rough approximation

        // Total delta-v
        double totalDeltaV = deltaV1 + deltaV2 + planeChangeDeltaV + eccentricityPenalty;

        // Transfer time (half period of transfer orbit)
        double transferTime = Math.PI * Math.sqrt(Math.pow(aTransfer, 3) / mu);

        // If plane change is significant, add wait time for proper alignment
        if (deltaI > Math.toRadians(15.0)) {
            // Rough approximation: may need to wait for nodal alignment
            double waitTime = Math.PI * Math.sqrt(Math.pow(a1, 3) / mu); // Half orbit
            transferTime += waitTime;
        }

        // Fuel required
        double fuelRequired = spacecraft.getFuelRequiredForDeltaV(totalDeltaV);

        // Position vectors (simplified - actual positions depend on true anomaly)
        Vector3D start = new Vector3D(a1, 0, 0);
        Vector3D end = new Vector3D(a2, 0, 0);

        return new Trajectory(start, end, totalDeltaV, transferTime, fuelRequired, totalDeltaV);
    }

    /**
     * Calculate delta-v required for a pure plane change
     * Most efficient when done at highest altitude (lowest velocity)
     *
     * @param velocity Current orbital velocity (m/s)
     * @param inclinationChange Change in inclination (radians)
     * @return Delta-v required (m/s)
     */
    public static double calculatePlaneChangeDeltaV(double velocity, double inclinationChange) {
        return 2.0 * velocity * Math.sin(Math.abs(inclinationChange) / 2.0);
    }

    /**
     * Estimate delta-v needed based on distance
     * This is a simplified heuristic
     */
    private static double estimateDeltaVForDistance(double distance) {
        // Rough heuristic: more distance requires more deltaV
        // Scale with square root of distance (similar to orbital mechanics)
        // Base assumption: 1 AU distance ≈ 30 km/s deltaV (rough Earth-Mars)

        double baseDistance = PhysicsConstants.AU;
        double baseDeltaV = 30000.0; // m/s
        return baseDeltaV * Math.sqrt(distance / baseDistance);
    }

    /**
     * Check if a spacecraft can complete a trajectory
     */
    public static boolean canCompleteTrajectory(Spacecraft spacecraft, Trajectory trajectory) {
        // Check fuel availability
        return !(spacecraft.getFuelMass() < trajectory.fuelRequired) && !(spacecraft.getAvailableDeltaV() < trajectory.deltaV);

        // Check if deltaV is achievable
    }

    /**
     * Calculate the relative velocity needed to match orbits with a target
     */
    public static double calculateMatchVelocity(Vector3D currentVel, Vector3D targetVel) {
        return currentVel.subtract(targetVel).magnitude();
    }

    /**
     * Calculate delta-v required to enter orbit around a body from an approach trajectory
     *
     * @param approachVelocity Velocity relative to the body when entering SOI (m/s)
     * @param bodyMass Mass of the body to orbit (kg)
     * @param bodyRadius Radius of the body (m)
     * @param targetOrbitAltitude Desired altitude above surface (m)
     * @return Delta-v required for orbital insertion (m/s)
     */
    public static double calculateOrbitalInsertionDeltaV(double approachVelocity,
                                                         double bodyMass,
                                                         double bodyRadius,
                                                         double targetOrbitAltitude) {
        double mu = PhysicsConstants.G * bodyMass;
        double r = bodyRadius + targetOrbitAltitude; // Orbital radius

        // Velocity needed for circular orbit at target altitude
        double orbitalVelocity = Math.sqrt(mu / r);

        // Periapsis velocity when approaching (conservation of energy)
        // v_periapsis^2 = v_infinity^2 + v_circular^2
        // where v_infinity is the approach velocity at infinity (SOI edge)
        double vPeriapsis = Math.sqrt(approachVelocity * approachVelocity +
                2 * mu / r);

        // Delta-v is the difference between periapsis velocity and orbital velocity
        return Math.abs(vPeriapsis - orbitalVelocity);
    }

    /**
     * Calculate delta-v to escape from orbit around a body
     *
     * @param orbitRadius Current orbital radius (m)
     * @param bodyMass Mass of the body (kg)
     * @return Delta-v required to escape (m/s)
     */
    public static double calculateEscapeDeltaV(double orbitRadius, double bodyMass) {
        double mu = PhysicsConstants.G * bodyMass;

        // Circular orbit velocity
        double vOrbit = Math.sqrt(mu / orbitRadius);

        // Escape velocity from this radius
        double vEscape = Math.sqrt(2 * mu / orbitRadius);

        // Delta-v is the difference
        return vEscape - vOrbit;
    }

    /**
     * Calculate gravity assist delta-v from a flyby
     * The Oberth effect allows more efficient burns deep in a gravity well
     *
     * @param bodyMass Mass of the body for flyby (kg)
     * @param periapsisRadius Closest approach distance (m)
     * @param incomingVelocity Velocity relative to body at infinity (m/s)
     * @param burnDeltaV Delta-v applied at periapsis (m/s)
     * @return Change in velocity at infinity after the maneuver (m/s)
     */
    public static double calculateOberthEffect(double bodyMass,
                                               double periapsisRadius,
                                               double incomingVelocity,
                                               double burnDeltaV) {
        double mu = PhysicsConstants.G * bodyMass;

        // Velocity at periapsis before burn
        double vPeriapsisBefore = Math.sqrt(incomingVelocity * incomingVelocity +
                2 * mu / periapsisRadius);

        // Velocity at periapsis after burn (assuming prograde burn)
        double vPeriapsisAfter = vPeriapsisBefore + burnDeltaV;

        // Velocity at infinity after burn
        double vInfinityAfter = Math.sqrt(vPeriapsisAfter * vPeriapsisAfter -
                2 * mu / periapsisRadius);

        // Change in v-infinity
        return vInfinityAfter - incomingVelocity;
    }

    /**
     * Calculate landing delta-v (simplified)
     * Assumes vertical descent with no atmosphere
     *
     * @param orbitAltitude Starting orbit altitude (m)
     * @param bodyMass Mass of the body (kg)
     * @param bodyRadius Radius of the body (m)
     * @return Approximate delta-v for landing (m/s)
     */
    public static double calculateLanding(double orbitAltitude,
                                          double bodyMass,
                                          double bodyRadius,
                                          Spacecraft spacecraft) {
        double mu = PhysicsConstants.G * bodyMass;
        double rOrbit = bodyRadius + orbitAltitude;

        // Orbital velocity
        double vOrbit = Math.sqrt(mu / rOrbit);

        // Surface velocity (if rotating, would subtract rotation speed)
        // For simplification, assume no rotation
        double vSurface = 0.0;

        // Velocity needed to deorbit and descend (Hohmann-like descent)
        // This is a simplification - real landing is more complex
        double vLanding = Math.sqrt(mu / bodyRadius);

        // Delta-v budget: deorbit + descent
        // Approximate as orbital velocity + landing velocity
        return spacecraft.getFuelRequiredForDeltaV(vOrbit + vLanding - vSurface);
    }

    /**
     * Calculate takeoff delta-v from a surface
     *
     * @param bodyMass Mass of the body (kg)
     * @param bodyRadius Radius of the body (m)
     * @param targetOrbitAltitude Desired orbit altitude (m)
     * @return Fuel Required for Takeoff
     */
    public static double calculateTakeoffDeltaV(double bodyMass,
                                                double bodyRadius,
                                                double targetOrbitAltitude,
                                                Spacecraft spacecraft) {
        double mu = PhysicsConstants.G * bodyMass;
        double rOrbit = bodyRadius + targetOrbitAltitude;

        // Velocity needed at surface to reach orbit (ignoring rotation)
        double vSurface = Math.sqrt(2 * mu * (1.0/bodyRadius - 1.0/(2*rOrbit)));

        // Orbital velocity at target altitude
        double vOrbit = Math.sqrt(mu / rOrbit);

        // Total delta-v is approximately these combined
        // (This is simplified - real rockets lose efficiency to gravity)
        return spacecraft.getFuelRequiredForDeltaV(vSurface + (vOrbit - Math.sqrt(mu / rOrbit)));
    }

    /**
     * Calculate sphere of influence (SOI) radius for a body
     * Region where the body's gravity dominates over the primary
     *
     * @param bodyMass Mass of the orbiting body (kg)
     * @param primaryMass Mass of the primary body (kg)
     * @param semiMajorAxis Distance between the bodies (m)
     * @return SOI radius (m)
     */
    public static double calculateSphereOfInfluence(double bodyMass,
                                                    double primaryMass,
                                                    double semiMajorAxis) {
        // SOI radius: r_SOI = a * (m/M)^(2/5)
        return semiMajorAxis * Math.pow(bodyMass / primaryMass, 0.4);
    }

    /**
     * Calculate complete orbital insertion trajectory
     * From approach to circular orbit
     *
     * @param spacecraft Spacecraft performing insertion
     * @param targetBody Body to orbit
     * @param approachVelocity Velocity relative to body at SOI (m/s)
     * @param orbitAltitude Desired orbit altitude above surface (m)
     * @return Trajectory with delta-v and fuel requirements
     */
    public static Trajectory calculateOrbitalInsertion(Spacecraft spacecraft,
                                                       CelestialBody targetBody,
                                                       double approachVelocity,
                                                       double orbitAltitude) {
        double insertionDeltaV = calculateOrbitalInsertionDeltaV(
                approachVelocity,
                targetBody.getMass(),
                targetBody.getRadius(),
                orbitAltitude
        );

        double fuelRequired = spacecraft.getFuelRequiredForDeltaV(insertionDeltaV);

        // Time for insertion burn (assume short impulsive burn)
        double burnTime = 60.0; // 1 minute typical

        Vector3D start = targetBody.getPosition();
        Vector3D end = targetBody.getPosition().add(
                new Vector3D(targetBody.getRadius() + orbitAltitude, 0, 0)
        );

        return new Trajectory(start, end, insertionDeltaV, burnTime, fuelRequired, targetBody.getCircularOrbitVelocity(targetBody.getRadius() + orbitAltitude));
    }

    public static Trajectory calculateRendezvousFromSpace(Vector3D startPos, Vector3D startVel,
                                                 Orbiter target,
                                                 Spacecraft spacecraft,
                                                 OrbitalSystem system) {
        OrbitInitializer targetOrbit = OrbitInitializer.calculateOrbitalInitializer(system.getCentralStar(),
                target.getPosition(),
                target.getVelocity());

        OrbitInitializer originOrbit = OrbitInitializer.calculateOrbitalInitializer(system.getCentralStar(), startPos, startVel);

        // Estimate transfer time
        Vector3D currentTargetPos = target.getPosition();
        double distance = startPos.distanceTo(currentTargetPos);
        double estimatedDeltaV = estimateDeltaVForDistance(distance);
        double estimatedTime = distance / (estimatedDeltaV / 2.0);

        double waitTime = calculateNextLaunchWindow(
                spacecraft.getPosition(),
                spacecraft.getVelocity(),
                target,
                targetOrbit,
                system
        );
        // Predict target position
        double totalTimeElapsed = waitTime + estimatedTime;
        Vector3D predictedTargetPos = predictOrbitalPosition(targetOrbit,
                totalTimeElapsed, system);

        Vector3D predictedOriginPos = predictOrbitalPosition(originOrbit, waitTime, system);

        Trajectory basicTrajectory = calculateDirectTransfer(startPos, predictedTargetPos,
                spacecraft);

        // Add plane change delta-v
        double startInclination = Math.atan2(startVel.getZ(),
                Math.sqrt(startVel.getX() * startVel.getX() +
                        startVel.getY() * startVel.getY()));
        double deltaInclination = Math.abs(targetOrbit.inclination() - startInclination);

        double planeChangeDV = deltaInclination > 0.001 ?
                calculatePlaneChangeDeltaV(startVel.magnitude(), deltaInclination) :
                0.0;

        double totalMissionTime = waitTime + basicTrajectory.travelTime;
        System.out.println("Total Mission Time : " + totalMissionTime + " Wait Time : " + waitTime + " travelTime" + basicTrajectory.travelTime);

        return new Trajectory(startPos, predictedTargetPos,
                predictedOriginPos,
                basicTrajectory.deltaV + planeChangeDV,
                totalMissionTime,
                waitTime,
                spacecraft.getFuelRequiredForDeltaV(basicTrajectory.deltaV + planeChangeDV),
                target.getVelocity().magnitude());
    }

    public static double calculateNextLaunchWindow(Vector3D startPos, Vector3D startVel,
                                                   Orbiter target,
                                                   OrbitInitializer targetOrbit,
                                                   OrbitalSystem system) {
        double mu = PhysicsConstants.G * system.getCentralStar().getMass();

        double targetAngle = Math.atan2(target.getPosition().getY(), target.getPosition().getX());
        double currentPhaseAngle = normalizeAngle(targetAngle - Math.atan2(startPos.getY(), startPos.getX()));

        double transferTime = Math.PI * Math.sqrt(Math.pow((startPos.magnitude() + targetOrbit.semiMajorAxis()) / 2, 3) / mu);
        double targetAngularVelocity = Math.sqrt(mu / Math.pow(targetOrbit.semiMajorAxis(), 3));
        double targetTravelAngle = targetAngularVelocity * transferTime;
        double optimalPhaseAngle = normalizeAngle(Math.PI - targetTravelAngle);

        double phaseAngleDifference = normalizeAngle(optimalPhaseAngle - currentPhaseAngle);

        double spacecraftAngularVelocity = startVel.magnitude() / startPos.magnitude();
        double waitTime = phaseAngleDifference / Math.abs(targetAngularVelocity - spacecraftAngularVelocity);

        double synodicPeriod = 2 * Math.PI / Math.abs(targetAngularVelocity - spacecraftAngularVelocity);
        if (waitTime > synodicPeriod / 2) {
            waitTime = synodicPeriod - waitTime;
        }

        return waitTime;
    }

    private static double normalizeAngle (double currentPhaseAngle) {
        if(currentPhaseAngle < 0) {
            return normalizeAngle(currentPhaseAngle + 2 * Math.PI);
        } else if(currentPhaseAngle >= 2 * Math.PI) {
            return normalizeAngle(currentPhaseAngle -  2 * Math.PI);
        } else {
            return currentPhaseAngle;
        }
    }

    /**
     * Predict where a body will be after a given time
     * Handles elliptical orbits using Kepler's equation
     */
    public static Vector3D predictOrbitalPosition(OrbitInitializer orbitStart,
                                                   double timeElapsed,
                                                   OrbitalSystem system) {

        // Calculate mean motion: n = sqrt(μ/a³)
        double meanMotion = Math.sqrt(Math.abs(PhysicsConstants.G * system.getCentralStar().getMass() / Math.pow(orbitStart.semiMajorAxis(), 3)));

        // Current mean anomaly from true anomaly
        double E0 = trueAnomalyToEccentricAnomaly(orbitStart.trueAnomaly(), orbitStart.eccentricity());

        // Future mean anomaly
        double M = E0 - orbitStart.eccentricity() * Math.sin(E0) + meanMotion * timeElapsed;
        M = M % (2 * Math.PI); // Normalize to [0, 2π]

        // Solve Kepler's equation: M = E - e*sin(E) for E
        double E = solveKeplersEquation(M, orbitStart.eccentricity());

        // Convert eccentric anomaly to true anomaly
        double nu = eccentricAnomalyToTrueAnomaly(E, orbitStart.eccentricity());
        double adjustedNu = Double.isNaN(nu) ? 0.0 : nu;
        // Calculate radius
        double r = orbitStart.semiMajorAxis() * (1 - orbitStart.eccentricity() * Math.cos(E));

        // Position in orbital plane
        double xOrbital = r * Math.cos(adjustedNu);
        double yOrbital = r * Math.sin(adjustedNu);

        // Rotate to 3D space using orbital elements
        double cosO = Math.cos(orbitStart.ascendingNode());
        double sinO = Math.sin(orbitStart.ascendingNode());
        double cosi = Math.cos(orbitStart.inclination());
        double sini = Math.sin(orbitStart.inclination());
        double cosw = Math.cos(orbitStart.periapsis());
        double sinw = Math.sin(orbitStart.periapsis());

        double x = xOrbital * (cosO * cosw - sinO * sinw * cosi) -
                yOrbital * (cosO * sinw + sinO * cosw * cosi);
        double y = xOrbital * (sinO * cosw + cosO * sinw * cosi) -
                yOrbital * (sinO * sinw - cosO * cosw * cosi);
        double z = xOrbital * (sinw * sini) + yOrbital * (cosw * sini);

        return new Vector3D(x, y, z);
    }

    /**
     * Solve Kepler's equation using Newton-Raphson iteration
     * M = E - e*sin(E)
     */
    private static double solveKeplersEquation(double M, double e) {
        double E = M;// Initial guess
        double tolerance = 1e-8;
        int maxIterations = 100;

        for (int i = 0; i < maxIterations; i++) {
            double f = E - e * Math.sin(E) - M;
            double fPrime = 1 - e * Math.cos(E);
            double deltaE = f / fPrime;
            E -= deltaE;

            if (Math.abs(deltaE) < tolerance) {
                break;
            }
        }

        return E;
    }

    /**
     * Convert true anomaly to eccentric anomaly
     */
    private static double trueAnomalyToEccentricAnomaly(double nu, double e) {
        double cosE = (e + Math.cos(nu)) / (1 + e * Math.cos(nu));
        double sinE = Math.sqrt(1 - e*e) * Math.sin(nu) / (1 + e * Math.cos(nu));
        return Math.atan2(Double.isNaN(sinE) ? 0.0 : sinE, cosE);
    }

    /**
     * Convert eccentric anomaly to true anomaly
     */
    private static double eccentricAnomalyToTrueAnomaly(double E, double e) {
        double cosNu = (Math.cos(E) - e) / (1 - e * Math.cos(E));
        double sinNu = Math.sqrt(1 - e*e) * Math.sin(E) / (1 - e * Math.cos(E));
        return Math.atan2(sinNu, cosNu);
    }

    /**
     * PIECEWISE TRAJECTORY: Calculate spacecraft position at any point during transfer
     * Uses a simple two-burn Hohmann-like transfer model
     *
     * @param trajectory The planned trajectory
     * @param elapsedTime Time since trajectory start (seconds)
     * @param centralMass Mass of central body (for orbital mechanics)
     * @return Position and velocity at the given time
     */
    public static PiecewiseState calculateTrajectoryState(Trajectory trajectory,
                                                          double elapsedTime,
                                                          double centralMass) {
        double mu = PhysicsConstants.G * centralMass;

        System.out.println("Elasped Time : " + elapsedTime);
        // Clamp time to trajectory duration
        if (elapsedTime < 0) elapsedTime = 0;
        if (elapsedTime > trajectory.travelTime) elapsedTime = trajectory.travelTime;

        // Simplified model: instant initial burn, coast, instant final burn
        // More realistic would be finite burn times
        // Note on Claude's documentation: Burn times are generally measured in seconds and the expectation is the
        // simulation is running on a minimum of one hour time steps so burn times are negligible.

        Vector3D startPos = trajectory.startPosition;
        Vector3D endPos = trajectory.endPosition;

        // Calculate transfer orbit parameters
        double r1 = startPos.magnitude();
        double r2 = endPos.magnitude();
        double a = (r1 + r2) / 2.0; // Semi-major axis of transfer orbit

        // Position along transfer ellipse
        double n = Math.sqrt(mu / Math.pow(a, 3)); // Mean motion
        double M = n * elapsedTime; // Mean anomaly

        // Solve for eccentric anomaly
        double e = Math.abs(r2 - r1) / (r1 + r2); // Eccentricity of transfer
        double E = solveKeplersEquation(M, e);

        // True anomaly
        double nu = eccentricAnomalyToTrueAnomaly(E, e);

        // Radius at this point
        double r = a * (1 - e * Math.cos(E));

        // Direction from start to end
        Vector3D direction = endPos.subtract(startPos).normalize();

        // Simplified: position along the straight line weighted by true anomaly
        // (Real trajectory would follow ellipse)
        double fraction = nu / Math.PI; // 0 to 1 over half orbit
        Vector3D currentPos = startPos.add(direction.multiply(r * fraction));

        // Velocity magnitude from vis-viva equation
        double v = Math.sqrt(mu * (2.0/r - 1.0/a));

        // Velocity direction (perpendicular to radius, in direction of motion)
        Vector3D velocityDirection = new Vector3D(-direction.getY(), direction.getX(), 0).normalize();
        Vector3D currentVel = velocityDirection.multiply(v);

        return new PiecewiseState(currentPos, currentVel, elapsedTime,
                elapsedTime / trajectory.travelTime);
    }


    public static double calculateSynodicPeriod(double orbit1Radius, double orbit2Radius,
                                                double centralMass) {
        double mu = PhysicsConstants.G * centralMass;

        double T1 = 2 * Math.PI * Math.sqrt(Math.pow(orbit1Radius, 3) / mu);
        double T2 = 2 * Math.PI * Math.sqrt(Math.pow(orbit2Radius, 3) / mu);

        return 1.0 / Math.abs(1.0 / T1 - 1.0 / T2);
    }
